"Количество = стоимость : цена. Например: 200 : 50 = 4.": "Саны = құны : бағасы. Мысалы: 200 : 50 = 4.",
"Справа от разряда округления стоит цифра 5. Что делаем?": "Дөңгелектейтін разрядтың оң жағында 5 цифры тұр. Не істейміз?",
