"неизвестно расстояние S: его находят по формуле S = v · t": "S қашықтығы белгісіз: оны S = v · t формуласымен табады",
"Одна булочка стоит 80 тг. Сколько можно купить на 800 тг?": "Бір тоқаш 80 тг тұрады. 800 тг-ге неше тоқаш алуға болады?",
