"Сколько квадратных метров в одном гектаре?": "Бір гектарда неше шаршы метр бар?",
"1 204 : 3 = 401 (ост. 1). Остаток не нуль.": "1 204 : 3 = 401 (қалд. 1). Қалдық нөл емес.",
