"Было: 2 кг по 60 тг. Стало: 5 кг по 60 тг.": "Болды: 2 кг, әр килограмы 60 тг. Енді: 5 кг, әр килограмы 60 тг.",
"Было: 5 кг по 90 тг. Стало: 2 кг по 90 тг.": "Болды: 5 кг, әр килограмы 90 тг. Енді: 2 кг, әр килограмы 90 тг.",
"Верно или неверно? Подумай и выбери ответ.": "Дұрыс па, бұрыс па? Ойлан да, жауап таңда.",
